import{_ as a}from"./chunks/asc_sync_notify.CDciJV2z.js";import{_ as n,o as c,a as p,b as e}from"./app.BnDjGmCD.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"asc_sync_wait","link":"/api/SIMD-API/c_api/sync/asc_sync_wait"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/asc_sync_wait.md","filePath":"api/SIMD-API/c_api/sync/asc_sync_wait.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788779718000}'),l={name:"api/SIMD-API/c_api/sync/asc_sync_wait.md"};function t(i,s,d,o,_,r){return c(),p("div",null,[...s[0]||(s[0]=[e('<div><article class="markdown-body"><h1>asc_sync_wait</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/sync/sync.h&quot;</code>。</p><p>如图1所示，与<a href="asc_sync_notify.html">asc_sync_notify</a>配对使用，用于实现AI Core内部不同流水之间的同步控制，<code>asc_sync_notify</code>和<code>asc_sync_wait</code>各自的功能如下：</p><ul><li><code>asc_sync_notify</code>：当源流水的前序指令的所有读写操作都完成之后，当前指令开始执行，并将硬件中的对应标志位设置为1。<code>asc_sync_notify</code>只是设置硬件中的对应标志位，并不会阻塞源流水中的下一个指令。</li><li><code>asc_sync_wait</code>：当目的流水执行到该指令时，如果发现硬件中对应标志位为0，目的流水的后续指令将一直被阻塞；如果发现硬件中对应标志位为1，则将硬件中对应标志位设置为0，同时目的流水的后续指令开始执行。</li></ul><p><strong>图1</strong> <code>asc_sync_notify</code>和<code>asc_sync_wait</code>接口功能示意图<br><img src="'+a+`" alt></p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span>
<span class="w">                                     </span><span class="n">pipe_t</span><span class="w"> </span><span class="n">tpipe</span><span class="p">,</span>
<span class="w">                                     </span><span class="n">event_t</span><span class="w"> </span><span class="n">id</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>pipe</td><td>输入</td><td>源流水类型，即“等待哪条流水的前序指令完成”。<br>参数的类型是<code>pipe_t</code>枚举，各个枚举取值的含义请参考<a href="./intra_core_sync_overview.html#%E7%A1%AC%E4%BB%B6%E6%B5%81%E6%B0%B4%E7%B1%BB%E5%9E%8B">硬件流水类型</a>。</td></tr><tr><td>tpipe</td><td>输入</td><td>目标流水类型，即“解除哪条流水的<code>asc_sync_wait</code>阻塞”。取值范围与<code>pipe</code>相同，为<code>pipe_t</code>枚举。</td></tr><tr><td>id</td><td>输入</td><td>同步事件ID，每对<code>pipe</code>与<code>tpipe</code>组合各自拥有8个独立的同步事件ID。取值范围为<code>event_t</code>枚举类型。</td></tr></tbody></table><p><code>event_t</code>枚举定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">typedef</span><span class="w"> </span><span class="k">enum</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">EVENT_ID0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID3</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID4</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID5</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID6</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="p">,</span>
<span class="w">    </span><span class="n">EVENT_ID7</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">7</span>
<span class="p">}</span><span class="w"> </span><span class="n">event_t</span><span class="p">;</span>
</code></pre></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><strong><code>pipe</code>与<code>tpipe</code>并非任意组合，两者组合的取值存在限制</strong>：针对不同产品，AIC与AIV中支持的组合不同，具体请参考<a href="intra_core_sync_overview.html#%E6%A0%B8%E5%86%85%E5%90%8C%E6%AD%A5%E5%88%86%E7%B1%BB">核内同步分类</a>中的<a href="intra_core_sync_overview.html#aic_intra_core_sync_combinations">表2</a>和<a href="intra_core_sync_overview.html#aiv_intra_core_sync_combinations">表3</a>。</li><li>相同源流水、相同目标流水、相同<code>id</code>下，连续使用<code>asc_sync_wait</code>会引发未定义行为。</li><li>本接口需与<code>asc_sync_notify</code>配对使用，配对的两条调用其<code>pipe</code>、<code>tpipe</code>、<code>id</code>三个参数必须完全一致。</li><li><code>pipe</code>与<code>tpipe</code>均不可取<code>PIPE_ALL</code>，否则触发异常。</li><li>每对<code>pipe</code>与<code>tpipe</code>组合各自拥有8个独立的同步事件ID。例如<code>PIPE_M</code>与<code>PIPE_V</code>的组合和<code>PIPE_V</code>与<code>PIPE_MTE3</code>的组合可同时使用相同的<code>id</code>值而互不干扰。</li><li>本接口可能阻塞<code>tpipe</code>（目标流水）的后续指令，直到对应的硬件标志位被置1。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>本接口需与<a href="asc_sync_notify.html">asc_sync_notify</a>配对使用，调用示例请参考<a href="asc_sync_notify.html">asc_sync_notify</a>中的“调用示例”章节。</p></article></div>`,1)])])}const y=n(l,[["render",t]]);export{w as __pageData,y as default};
